MoveCallBuilder requestWithdraw(
    {dynamic arguments, String? package, Map<String, dynamic>? config}) {
  final packageAddress = package ??
      (config?['predictPackageId'] as String?) ??
      '@local-pkg/deepbook_predict';
  return (tx) => tx.moveCall(
        '$packageAddress::plp::request_withdraw',
        arguments: normalizeMoveArguments(
            tx,
            withConfigDefaults(arguments, config,
                const {'vault': 'poolVault', 'config': 'protocolConfig'}),
            [
              null,
              null,
              null,
              null,
              'u64',
              'u64',
              '0x2::accumulator::AccumulatorRoot',
              '0x2::clock::Clock'
            ],
            [
              'vault',
              'wrapper',
              'auth',
              'config',
              'amount',
              'minUsdcOut'
            ]),
      );
}

